import type { LookColors } from './looks.ts';

/**
 * The sites the home page's demonstration "builds".
 *
 * Every one of them is invented: the studios, the clinic and the fair do not
 * exist, and nothing here was generated by a model. They are the content of
 * a drawing, which is what the hero says it is. Real output is on /examples,
 * where each entry is exactly what vibld produced from the prompt beside it.
 *
 * The colours are each site's imaginary "direction A", measured with the
 * repository's contrast checker in `test/looks.test.ts` like every other
 * palette a miniature is drawn in.
 */

export type DemoSiteId =
  'pottery' | 'portfolio' | 'saas' | 'cafe' | 'clinic' | 'event' | 'app';

export interface DemoSite {
  id: DemoSiteId;
  /** The suggestion chip's label. */
  label: string;
  /** The project name the builder's title bar shows. */
  slug: string;
  prompt: string;
  /** The component name of the third section, for the code and the inspector. */
  section: string;
  text: {
    brand: string;
    links: readonly [string, string, string];
    nav: string;
    eyebrow: string;
    headline: string;
    lead: string;
    primary: string;
    secondary: string;
    cards: readonly [
      readonly [string, string],
      readonly [string, string],
      readonly [string, string],
    ];
  };
  /** How full each card's bar is, in percent. */
  bars: readonly [number, number, number];
  colors: LookColors;
}

/** The surfaces a demonstration site uses, from a handful of its colours. */
function siteColors(c: {
  page: string;
  ink: string;
  soft: string;
  card: string;
  primary: string;
  line: string;
  deco: readonly [string, string, string, string];
}): LookColors {
  return {
    page: { fill: c.page, ink: c.ink, soft: c.soft },
    card: { fill: c.card, ink: c.ink, soft: c.soft },
    panel: { fill: c.card, ink: c.ink, soft: c.soft },
    primary: { fill: c.primary, ink: '#FFFFFF' },
    accent: { fill: c.primary, ink: '#FFFFFF' },
    line: c.line,
    deco: c.deco,
  };
}

