export const DEMO_SITE_IDS = Object.keys(DEMO_SITES) as DemoSiteId[];

/**
 * Which demonstration a typed request most resembles.
 *
 * Keyword matching and nothing more, which is exactly as clever as a page
 * that does not call a model can honestly be. Anything unmatched builds the
 * pottery studio.
 */
const KEYWORDS: readonly (readonly [DemoSiteId, RegExp])[] = [
  ['portfolio', /portfolio|photograph|artist|illustrat|designer/i],
  ['cafe', /caf[eé]|coffee|bakery|restaurant|\bbar\b|menu/i],
  ['clinic', /clinic|dental|dentist|physio|doctor|therap|health/i],
  ['event', /event|fair|festival|conference|wedding|meetup|concert/i],
  ['app', /habit|tracker|todo|to-do|\bapp\b/i],
  ['saas', /saas|startup|invoice|product|tool|software|landing/i],
  ['pottery', /pottery|ceramic|class|course|workshop|lesson/i],
];

export function siteForRequest(request: string): DemoSiteId {
  for (const [id, pattern] of KEYWORDS) {
    if (pattern.test(request)) return id;
  }
  return 'pottery';
}
